python3 -B - <<'PY'
from client import save
class Capture:
    def __init__(self):
        self.calls = []
        self.result = {'saved': True}
    def put(self, path, body):
        self.calls.append((path, body))
        return self.result
for raw, expected in [('  Ada  ', 'Ada'), ('Ada Lovelace', 'Ada Lovelace'), ('', ''), (' \t\n ', ''), ('\tAda\n', 'Ada'), ('\u00a0Ada\u00a0', 'Ada')]:
    transport = Capture()
    result = save(transport, raw)
    assert result is transport.result
    assert transport.calls == [('/settings', {'display_name': expected})]
    print(repr(raw), '->', repr(expected), 'request and response verified')
class Failing:
    def put(self, path, body):
        raise OSError('simulated transport failure')
try:
    save(Failing(), ' Ada ')
except OSError as error:
    assert str(error) == 'simulated transport failure'
    print('Transport exception propagated')
else:
    raise AssertionError('Expected transport error')
PY
